// Webhook output has the request body under $json.body.
// Flatten the envelope and its payload into one item.
const b = $input.first().json.body || {};
if (!b.runId) throw new Error('Missing runId in the request body');
return [{
  json: {
    runId: b.runId,
    ownerId: b.ownerId ?? null,
    jobId: b.jobId ?? null,
    agentId: b.agentId ?? null,
    ...(b.payload || {}),
  },
}];

// Which side may ask for which action. Anything else stops here.
const e = $input.first().json;
const SIDE = { post_job: 'buyer', accept_offer: 'buyer', fund_job: 'buyer',
               place_bid: 'seller', submit_delivery: 'seller' };
if (!SIDE[e.action]) throw new Error('Action not allowed: ' + e.action);
if (SIDE[e.action] !== e.side) throw new Error(`${e.action} must be signed by the ${SIDE[e.action]} side`);
return [{ json: { ...e, milestoneIdx: e.milestoneIdx ?? 0, bidId: e.bidId ?? null } }];

// Arguments are rebuilt from the database, never taken from the request.
// USDC has 6 decimals: 40 USDC = "40000000".
const e = $('Allow-list').first().json;
const j = $input.first().json;
if (!j.job_id) throw new Error('Job not found');
const units = (x) => BigInt(Math.round(Number(x) * 1e6)).toString();
const ms = (b) => (Array.isArray(b?.proposed_milestones) && b.proposed_milestones.length
  ? b.proposed_milestones.map((m) => units(m.amount))
  : [units(b?.price ?? 0)]);
let args, amount = null;

switch (e.action) {
  case 'post_job':
    args = { job_id: j.job_id, category: j.category, spec_hash: j.spec_hash };
    break;
  case 'place_bid':
    if (!j.bid) throw new Error('Bid not found');
    args = { job_id: j.job_id, price: units(j.bid.price), milestones: ms(j.bid) };
    break;
  case 'accept_offer':
    if (!j.bid) throw new Error('No bid to accept');
    if (!j.spec_hash) throw new Error('No locked acceptance spec: lock the spec before accepting');
    args = { job_id: j.job_id, bid_id: j.bid.id, seller: j.seller_account,
             milestones: ms(j.bid), spec_hash: j.spec_hash };
    amount = Number(j.bid.price);
    break;
  case 'fund_job':
    if (!j.milestone) throw new Error('Milestone not found');
    args = { job_id: j.job_id, milestone_idx: j.milestone.idx };
    amount = Number(j.milestone.amount);
    break;
  case 'submit_delivery':
    if (!j.delivery) throw new Error('No delivery recorded for this milestone');
    args = { job_id: j.job_id, milestone_idx: e.milestoneIdx, commit_sha: j.delivery.commit_sha };
    break;
}
return [{ json: {
  signer: e.side === 'buyer' ? 'tx-buyer' : 'tx-seller',
  method: e.action, args, amount,
  ownerId: e.ownerId || j.buyer_id, jobId: j.job_id,
} }];

const env = $('Read envelope').first().json;
const r = $input.first().json;
const amount = r.amount != null ? ` ${r.amount} USDC` : '';
const message = r.ok
  ? `${r.method}${amount} signed by ${r.signer} (tx ${r.txHash})`
  : `Contract refused ${r.method}${amount}: ${r.error} [${r.rejectedBy}]`;
return [{ json: {
  runId: env.runId, ownerId: env.ownerId, agentId: env.agentId, jobId: env.jobId,
  actorLabel: 'Transaction agent', message, severity: r.ok ? 'ok' : 'block',
  data: { method: r.method, ok: r.ok, txHash: r.txHash, explorer: r.explorer,
          rejectedBy: r.rejectedBy, amount: r.amount },
  notify: { runId: env.runId, role: 'transaction', ok: r.ok, jobId: env.jobId,
            result: { method: r.method, txHash: r.txHash, explorer: r.explorer, rejectedBy: r.rejectedBy },
            error: r.ok ? null : r.error },
} }];
